import type {
  ActivateDeviceResult,
  ActivationRepository,
  DeviceRepository,
  LetterRepository,
  LetterRecord,
  Repos,
} from "./types.js";

/// D1-backed repositories. All SQL lives here; the handlers never touch
/// D1 directly. Timestamps are UTC ISO strings generated by the caller.
///
/// Concurrency notes:
/// - `insertLetter` uses INSERT OR IGNORE: two requests racing on the
///   same id or client_request_id can never raise a unique-constraint
///   error — the loser reads the winner's row and reports created=false.
/// - `activateDevice` runs a single `db.batch()` (a transaction): the
///   code is marked used AND the device row is inserted together. The
///   insert is conditional on the code row actually flipping to used,
///   so a lost race consumes neither the code nor the device slot.
export function createRepos(db: D1Database): Repos {
  return {
    letters: d1Letters(db),
    activations: d1Activations(db),
    devices: d1Devices(db),
    activateDevice: d1ActivateDevice(db),
  };
}

function rowToLetter(row: Record<string, unknown>): LetterRecord {
  return {
    seq: Number(row.seq),
    id: String(row.id),
    body: String(row.body),
    created_at: String(row.created_at),
    opened_at: row.opened_at === null ? null : String(row.opened_at),
  };
}

function d1Letters(db: D1Database): LetterRepository {
  return {
    async insertLetter(input) {
      // INSERT OR IGNORE absorbs BOTH unique constraints (id and
      // client_request_id) atomically — no SELECT-then-INSERT race.
      const inserted = await db
        .prepare(
          `INSERT OR IGNORE INTO letters (id, body, created_at, client_request_id)
           VALUES (?, ?, ?, ?)`
        )
        .bind(input.id, input.body, input.createdAt, input.clientRequestId ?? null)
        .run();
      if ((inserted.meta?.changes ?? 0) === 0) {
        // We lost the race (or a retry): return the existing row.
        const existing = await db
          .prepare(
            `SELECT seq, id, body, created_at, opened_at FROM letters
             WHERE id = ? OR (client_request_id IS NOT NULL AND client_request_id = ?)
             LIMIT 1`
          )
          .bind(input.id, input.clientRequestId ?? null)
          .first<Record<string, unknown>>();
        if (!existing) throw new Error("letter insert conflict but no existing row");
        return { record: rowToLetter(existing), created: false };
      }
      const row = await db
        .prepare(`SELECT seq, id, body, created_at, opened_at FROM letters WHERE id = ?`)
        .bind(input.id)
        .first<Record<string, unknown>>();
      if (!row) throw new Error("letter insert returned no row");
      return { record: rowToLetter(row), created: true };
    },

    async listLetters(afterSeq, limit) {
      const result = await db
        .prepare(
          `SELECT seq, id, body, created_at, opened_at FROM letters
           WHERE seq > ? ORDER BY seq ASC LIMIT ?`
        )
        .bind(afterSeq, limit)
        .all<Record<string, unknown>>();
      return result.results.map(rowToLetter);
    },

    async findLetterById(id) {
      const row = await db
        .prepare(`SELECT seq, id, body, created_at, opened_at FROM letters WHERE id = ?`)
        .bind(id)
        .first<Record<string, unknown>>();
      return row ? rowToLetter(row) : null;
    },

    async deleteLetter(id) {
      const result = await db.prepare(`DELETE FROM letters WHERE id = ?`).bind(id).run();
      return (result.meta?.changes ?? 0) > 0;
    },

    async markOpened(id, at) {
      const before = await db
        .prepare(`SELECT opened_at FROM letters WHERE id = ?`)
        .bind(id)
        .first<{ opened_at: string | null }>();
      if (!before) throw new Error("letter not found");
      const alreadyOpened = before.opened_at !== null;
      if (!alreadyOpened) {
        await db
          .prepare(`UPDATE letters SET opened_at = ? WHERE id = ? AND opened_at IS NULL`)
          .bind(at, id)
          .run();
      }
      const row = await db
        .prepare(`SELECT seq, id, body, created_at, opened_at FROM letters WHERE id = ?`)
        .bind(id)
        .first<Record<string, unknown>>();
      if (!row) throw new Error("letter not found");
      return { record: rowToLetter(row), alreadyOpened };
    },
  };
}

function d1Activations(db: D1Database): ActivationRepository {
  return {
    async createCode(codeHash, createdAt, expiresAt) {
      await db
        .prepare(`INSERT INTO activation_codes (code_hash, created_at, expires_at) VALUES (?, ?, ?)`)
        .bind(codeHash, createdAt, expiresAt)
        .run();
    },

    async listCodes() {
      const result = await db
        .prepare(
          `SELECT code_hash, created_at, expires_at, used_at FROM activation_codes ORDER BY created_at DESC`
        )
        .all<{ code_hash: string; created_at: string; expires_at: string; used_at: string | null }>();
      return result.results;
    },
  };
}

function d1Devices(db: D1Database): DeviceRepository {
  return {
    async findDeviceByTokenHash(tokenHash) {
      const row = await db
        .prepare(
          `SELECT id, label, created_at, revoked_at FROM devices WHERE token_hash = ?`
        )
        .bind(tokenHash)
        .first<{ id: string; label: string; created_at: string; revoked_at: string | null }>();
      return row ?? null;
    },

    async listDevices() {
      const result = await db
        .prepare(`SELECT id, label, created_at, revoked_at FROM devices ORDER BY created_at ASC`)
        .all<{ id: string; label: string; created_at: string; revoked_at: string | null }>();
      return result.results;
    },

    async revokeDevice(id, at) {
      const result = await db
        .prepare(`UPDATE devices SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL`)
        .bind(at, id)
        .run();
      return (result.meta?.changes ?? 0) > 0;
    },
  };
}

/// One atomic "redeem code + create device" sequence.
function d1ActivateDevice(db: D1Database): Repos["activateDevice"] {
  return async (input): Promise<ActivateDeviceResult> => {
    const codeRow = await db
      .prepare(`SELECT created_at, expires_at, used_at FROM activation_codes WHERE code_hash = ?`)
      .bind(input.codeHash)
      .first<{ created_at: string; expires_at: string; used_at: string | null }>();
    if (!codeRow) return { ok: false, reason: "invalid" };
    if (codeRow.used_at !== null) return { ok: false, reason: "used" };
    if (codeRow.expires_at < input.at) return { ok: false, reason: "expired" };

    // The batch executes as one transaction. Statement B only inserts
    // the device when statement A actually flipped the code to used for
    // THIS attempt (EXISTS on used_at = our timestamp + device_id), so
    // even a concurrent redeem can never produce a device row for a
    // code it did not win. If A changes 0 rows, B inserts 0 rows and
    // the code stays in its original (used-by-someone-else) state.
    const markCode = db
      .prepare(
        `UPDATE activation_codes SET used_at = ?, device_id = ?
         WHERE code_hash = ? AND used_at IS NULL`
      )
      .bind(input.at, input.deviceId, input.codeHash);
    const insertDevice = db
      .prepare(
        `INSERT INTO devices (id, token_hash, label, created_at)
         SELECT ?, ?, ?, ?
         WHERE EXISTS (
           SELECT 1 FROM activation_codes
           WHERE code_hash = ? AND used_at = ? AND device_id = ?
         )`
      )
      .bind(input.deviceId, input.tokenHash, input.label, input.at, input.codeHash, input.at, input.deviceId);

    const [markResult, insertResult] = await db.batch([markCode, insertDevice]);
    const markChanges = markResult?.meta?.changes ?? 0;
    const insertChanges = insertResult?.meta?.changes ?? 0;
    if (markChanges === 0 || insertChanges === 0) {
      // Lost a race: someone else redeemed this code first.
      return { ok: false, reason: "used" };
    }
    return {
      ok: true,
      device: {
        id: input.deviceId,
        label: input.label,
        created_at: input.at,
        revoked_at: null,
      },
    };
  };
}
